insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 43, 'Porém sabei isto: se o dono de casa soubesse a que hora da noite o ladrão viria, vigiaria, e não deixaria invadir a sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 44, 'Portanto também vós estai prontos, porque o Filho do homem virá na hora que não esperais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 45, 'Pois quem é o servo fiel e prudente, ao qual o seu senhor pôs sobre os seus trabalhadores, para [lhes] dar alimento no tempo devido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 46, 'Feliz será aquele servo a quem, quando o seu senhor vier, achar fazendo assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 47, 'Em verdade vos digo que ele o porá sobre todos os seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 48, 'Porém se aquele servo mau disser em seu coração: “Meu senhor está demorando a chegar”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 49, 'e começar a espancar os [seus] companheiros de serviço, e a comer, e a beber com os beberrões,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 50, 'o senhor daquele servo chegará num dia que ele não espera, e numa hora que ele não sabe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 51, 'e o despedaçará, e porá sua parte com os hipócritas; ali haverá pranto e ranger de dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 1, 'Então o Reino dos céus será semelhante a dez virgens, que tomaram suas lâmpadas, e saíram ao encontro do noivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 2, 'E cinco delas eram prudentes, e cinco tolas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 3, 'As tolas, quando tomaram as suas lâmpadas, não tomaram azeite consigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 4, 'Mas as prudentes tomaram azeite nos seus frascos, com as suas lâmpadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 5, 'O noivo demorou, por isso todas cochilaram e adormeceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 6, 'Mas à meia-noite houve um grito: “Eis que vem o noivo! Ide ao seu encontro!”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 7, 'Então todas aquelas virgens se levantaram, e prepararam suas lâmpadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 8, 'E as tolas disseram às prudentes: “Dai-nos do vosso azeite, porque as nossas lâmpadas estão se apagando”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 9, 'Mas as prudentes responderam: “ [Não] ,para que não falte a nós e a vós; em vez disso, ide aos vendedores, e comprai para vós mesmas”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 10, 'Enquanto elas foram comprar, veio o noivo. As que estavam preparadas entraram com ele à festa do casamento, e fechou-se a porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 11, 'Depois vieram também as outras virgens, dizendo: “Senhor, Senhor, abre-nos!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 12, 'Mas ele respondeu: “Em verdade vos digo que não vos conheço”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 13, 'Portanto, vigiai, porque não sabeis o dia nem a hora em que o Filho do homem virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 14, 'Pois [é] como um homem, que partindo para fora do país, chamou seus servos, e lhes entregou os seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 15, 'E a um deu cinco talentos, a outro dois, e ao terceiro um, a cada um conforme a sua habilidade, e logo depois partiu em viagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 16, 'Em seguida, o que havia recebido cinco talentos foi fazer negócios com eles, e obteve outros cinco talentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 17, 'E, semelhantemente, o que [havia recebido] dois ganhou também outros dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 18, 'Mas o que tinha recebido um foi cavar a terra, e escondeu o dinheiro do seu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 19, 'Muito tempo depois, o senhor daqueles servos veio fazer contas com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 20, 'O que havia recebido cinco talentos chegou trazendo-lhe outros cinco talentos, e disse: ”Senhor, cinco talentos me entregaste, eis que ganhei com eles outros cinco talentos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 21, 'E o seu senhor lhe disse: “ [Muito] bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 22, 'E chegando-se também o que havia recebido dois talentos, disse: “Senhor, dois talentos me entregaste, eis que ganhei com eles outros dois talentos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 23, 'Seu senhor lhe disse: “ [Muito] bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 24, 'Mas, chegando também o que havia recebido um talento, disse: “Senhor, eu te conhecia, que és homem duro, que colhes onde não semeaste, e ajuntas onde não espalhaste;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 25, 'E eu, atemorizado, fui e escondi o teu talento na terra; eis aqui tens o que é teu”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 26, 'Porém seu senhor lhe respondeu: “Servo mau e preguiçoso! Sabias que colho onde não semeei, e ajunto onde não espalhei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 27, 'Devias, portanto, ter depositado o meu dinheiro com os banqueiros e, quando eu voltasse, receberia o que é meu com juros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 28, 'Por isso, tirai dele o talento, e dai-o ao que tem dez talentos”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 29, 'Pois a todo aquele que tiver, lhe será dado, e terá em abundância; porém ao que não tiver, até o que tem lhe será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 30, '“E lançai o servo inútil às trevas de fora (ali haverá pranto e ranger de dentes)”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 31, 'E quando o Filho do homem vier em sua glória, e todos os santos anjos com ele, então ele se assentará sobre o trono de sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 32, 'E serão ajuntadas diante dele todas as nações, e separará [as pessoas] umas das outras, assim como o pastor separa as ovelhas dos bodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 33, 'E porá as ovelhas à sua direita, porém os bodes à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 34, 'Então o Rei dirá o rei aos que estiverem à sua direita: “Vinde, benditos de meu Pai! Herdai o Reino que está preparado para vós desde a fundação do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 35, 'Pois tive fome, e me destes de comer; tive sede, e me destes de beber; fui forasteiro, e me acolhestes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 36, '[estive] nu, e me vestistes; [estive] doente, e cuidastes de mim; estive na prisão, e me visitastes”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 37, 'Então os justos lhe perguntarão: “Senhor, quando te vimos com fome, e [te] demos de comer, ou com sede, e [te] demos de beber?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 38, 'E quando te vimos forasteiro, e [te] acolhemos, ou nu, e te vestimos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 39, 'E quando te vimos doente, ou na prisão, e viemos te visitar?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 40, 'E o Rei lhes responderá: “Em verdade vos digo que, todas as vezes que fizestes a um destes menores dos meus irmãos, fizestes a mim”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 41, 'Então dirá também aos que [estiverem] à esquerda: “Apartai-vos de mim, malditos, ao fogo eterno, preparado para o Diabo e os seus anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 42, 'Pois tive fome, e não me destes de comer; tive sede, e não me destes de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 43, 'Fui forasteiro, e não me acolhestes; [estive] nu, e não me vestistes; [estive] doente, e na prisão, e não me visitastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 44, 'Então também eles lhe perguntarão: “Senhor, quando te vimos com fome, ou com sede, ou forasteiro, ou nu, ou doente, ou na prisão, e não te servimos?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 45, 'Então ele lhes responderá, dizendo: “Em verdade vos digo que, todas as vezes que não fizestes a um destes menores, não fizestes a mim”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 25, 46, 'E estes irão ao tormento eterno, porém os justos à vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 1, 'E aconteceu que, quando Jesus terminou todas estas palavras, disse aos seus discípulos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 2, 'Vós bem sabeis que daqui a dois dias é a Páscoa, e o Filho do homem será entregue para ser crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 3, 'Então os chefes dos sacerdotes, os escribas, e os anciãos do povo se reuniram na casa do sumo sacerdote, que se chamava Caifás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 4, 'E conversaram a fim de, usando mentira, prenderem Jesus, e [o] matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 5, 'Porém diziam: Não na festa, para que não haja tumulto entre o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 6, 'Enquanto Jesus estava em Betânia, na casa de Simão o leproso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 7, 'veio a ele uma mulher com um vaso de alabastro, de óleo perfumado de grande valor, e derramou sobre a cabeça dele, enquanto estava sentado à mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 8, 'E quando os seus discípulos viram, ficaram indignados, dizendo: Para que este desperdício?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 9, 'Pois esse óleo perfumado podia ter sido vendido por muito, e o dinheiro dado aos pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 10, 'Porém Jesus, sabendo [disso] ,disse-lhes: Por que perturbais a esta mulher? Ora, ela me fez uma boa obra!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 11, 'Pois vós sempre tendes os pobres convosco, porém nem sempre me tereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 12, 'Pois ela, ao derramar este óleo perfumado sobre o meu corpo, ela o fez para [preparar] o meu sepultamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 13, 'Em verdade vos digo que, onde quer que este Evangelho em todo o mundo for pregado, também se dirá o que ela fez, para que seja lembrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 14, 'Então um dos doze, chamado Judas Iscariotes, foi aos chefes dos sacerdotes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 15, 'e disse: O que quereis me dar, para que eu o entregue a vós? E eles lhe determinaram trinta [moedas] de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 16, 'E desde então ele buscava oportunidade para o entregar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 17, 'E no primeiro [dia da festa] dos pães sem fermento, os discípulos vieram a Jesus lhe perguntar: Onde queres que te preparemos para comer a Páscoa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 18, 'E ele respondeu: Ide à cidade a um tal, e dizei-lhe: “O Mestre diz: ‘Meu tempo está perto. Contigo celebrarei a Páscoa com os meus discípulos’”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 19, 'Os discípulos fizeram como Jesus havia lhes mandado, e prepararam a Páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 20, 'E vindo o anoitecer, ele se assentou à mesa com os doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 21, 'E enquanto comiam, disse: Em verdade vos digo que um de vós me trairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 22, 'Eles ficaram muito tristes, e cada um deles começou a lhe perguntar: Por acaso sou eu, Senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 23, 'E ele respondeu: O que mete comigo a mão no prato, esse me trairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 24, 'De fato, o Filho do homem vai assim como dele está escrito; mas ai daquele homem por quem o Filho do homem é traído! Bom seria a tal homem se não houvesse nascido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 25, 'E Judas, o que o traía, perguntou: Por acaso sou eu, Rabi? [Jesus] lhe disse: Tu o disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 26, 'E enquanto comiam, Jesus tomou o pão, abençoou-o, e o partiu. Então o deu aos discípulos, e disse: Tomai, comei; isto é o meu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 27, 'Em seguida tomou o cálice, deu graças, e o deu a eles, dizendo: Bebei dele todos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 28, 'porque este é o meu sangue, o [sangue] do novo testamento, o qual é derramado por muitos, para o perdão de pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 29, 'E eu vos digo que desde agora não beberei deste fruto da vide, até aquele dia, quando convosco o beber, novo, no reino do meu Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 30, 'E depois de cantarem um hino, saíram para o monte das Oliveiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 31, 'Então Jesus lhes disse: Todos vós falhareis comigo esta noite; porque está escrito: “Ferirei o pastor, e as ovelhas do rebanho serão dispersas”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 32, 'Mas, depois que eu for ressuscitado, irei adiante de vós para a Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 33, 'Pedro, porém, respondeu-lhe: Ainda que todos falhem contigo, eu nunca falharei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 34, 'Jesus lhe disse: Em verdade te digo que, nesta mesma noite, antes do galo cantar, tu me negarás três vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 35, 'Pedro lhe respondeu: Ainda que eu tenha de morrer contigo, em nenhuma maneira te negarei. E todos os discípulos disseram o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 36, 'Então Jesus veio com eles a um lugar chamado Getsêmani, e disse aos discípulos: Ficai sentados aqui, enquanto eu vou ali orar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 37, 'Enquanto trazia consigo Pedro e os dois filhos de Zebedeu, ele começou a se entristecer e a se angustiar muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 38, 'Então lhes disse: Minha alma está completamente triste até a morte. Ficai aqui, e vigiai comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 39, 'E indo um pouco mais adiante, prostrou-se sobre o seu rosto, orando, e dizendo: Meu Pai, se é possível, passe de mim este cálice; porém, não [seja] como eu quero, mas sim como tu [queres] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 40, 'Então voltou aos seus discípulos, e os encontrou dormindo; e disse a Pedro: Então, nem sequer uma hora pudestes vigiar comigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 41, 'Vigiai e orai, para que não entreis em tentação. De fato, o espírito [está] pronto, mas a carne [é] fraca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 42, 'Ele foi orar pela segunda vez, dizendo: Meu Pai, se este cálice não pode passar de mim sem que eu o beba, faça-se a tua vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 43, 'Quando voltou, achou-os outra vez dormindo, pois os seus olhos estavam pesados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 44, 'Então os deixou, e foi orar pela terceira vez, dizendo as mesmas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 45, 'Depois veio aos seus discípulos, e disse-lhes: Agora dormi e descansai. Eis que chegou a hora em que o Filho do homem é entregue em mãos de pecadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 46, 'Levantai-vos, vamos! Eis que chegou o que me trai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 47, 'Enquanto ele ainda estava falando, eis que veio Judas, um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes e dos anciãos do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 48, 'O seu traidor havia lhes dado sinal, dizendo: Aquele a quem eu beijar, é esse. Prendei-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 49, 'Logo ele se aproximou de Jesus, e disse: Felicitações, Rabi! e o beijou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 50, 'Jesus, porém, lhe perguntou: Amigo, para que vieste? Então chegaram, agarraram Jesus, e o prenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 51, 'E eis que um dos que [estavam] com Jesus estendeu a mão, puxou de sua espada, e feriu o servo do sumo sacerdote, cortando-lhe uma orelha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 52, 'Jesus, então, lhe disse: Põe de volta tua espada ao seu lugar, pois todos os que pegarem espada, pela espada perecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 53, 'Ou, por acaso, pensas tu que eu não posso agora orar ao meu Pai, e ele me daria mais de doze legiões de anjos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 54, 'Como, pois, se cumpririam as Escrituras [que dizem] que assim tem que ser feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 55, 'Naquela hora Jesus disse às multidões: Como a um ladrão saístes com espadas e bastões para me prender? Todo dia eu me sentava convosco, ensinando no templo, e não me prendestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 56, 'Porém tudo isto aconteceu para que as Escrituras dos profetas se cumpram.Então todos os discípulos o abandonaram, e fugiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 57, 'Os que prenderam Jesus o trouxeram [à casa] de Caifás, o sumo sacerdote, onde os escribas e os anciãos estavam reunidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 58, 'E Pedro o seguia de longe, até o pátio do sumo sacerdote; e entrou, e se assentou com os servos, para ver o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 59, 'Os chefes dos sacerdotes, os anciãos, e todo o supremo conselho buscavam falso testemunho contra Jesus, para poderem matá-lo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 60, 'mas não encontravam. E ainda que muitas falsas testemunhas se apresentavam, [contudo] não encontravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 61, 'Mas, por fim, vieram duas falsas testemunhas, que disseram: Este disse: “Posso derrubar o Templo de Deus e reconstruí-lo em três dias”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 62, 'Então o sumo sacerdote se levantou, e lhe perguntou: Não respondes nada ao que eles testemunham contra ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 63, 'Porém Jesus ficava calado. Então o sumo sacerdote lhe disse: Ordeno-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 64, 'Jesus lhe disse: Tu o disseste. Porém eu vos digo que, desde agora, vereis o Filho do homem, sentado à direita do Poderoso, e vindo sobre as nuvens do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 65, 'Então o sumo sacerdote rasgou suas roupas, e disse: Ele blasfemou! Para que necessitamos mais de testemunhas? Eis que agora ouvistes a sua blasfêmia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 66, 'Que vos parece?E eles responderam: Culpado de morte ele é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 67, 'Então lhe cuspiram no rosto, e lhe deram socos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 68, 'Outros lhe deram bofetadas, e diziam: Profetiza-nos, ó Cristo, quem é o que te feriu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 69, 'Pedro estava sentado fora no pátio. Uma serva aproximou-se dele, e disse: Também tu estavas com Jesus, o galileu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 70, 'Mas ele o negou diante de todos, dizendo: Não sei o que dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 71, 'E quando ele saiu em direção à entrada, outra o viu, e disse aos que ali [estavam] : Também este estava com Jesus, o nazareno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 72, 'E ele o negou outra vez com um juramento: Não conheço [esse] homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 73, 'Pouco depois, os que ali estavam se aproximaram, e disseram a Pedro: Verdadeiramente também tu és um deles, pois a tua fala te denuncia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 74, 'Então ele começou a amaldiçoar e a jurar: Não conheço [esse] homem!E imediatamente o galo cantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 26, 75, 'Então Pedro se lembrou da palavra de Jesus, que lhe dissera: Antes do galo cantar, tu me negarás três vezes. Assim ele saiu, e chorou amargamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 1, 'Vinda a manhã, todos os chefes dos sacerdotes e anciãos do povo juntamente se aconselharam contra Jesus, para o matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 2, 'E o levaram amarrado, e o entregaram a Pôncio Pilatos, o governador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 3, 'Então Judas, o que o havia traído, ao ver que [Jesus] já estava condenado, devolveu, sentindo remorso, as trinta [moedas] de prata aos chefes dos sacerdotes e aos anciãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 4, 'e disse: Pequei, traindo sangue inocente. Porém eles disseram: Que nos interessa? Isso é problema teu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 5, 'Então ele lançou as [moedas] de prata no templo, saiu, e foi enforcar-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 6, 'Os chefes dos sacerdotes tomaram as [moedas] de prata, e disseram: Não é lícito pô-las no tesouro das ofertas, pois isto é preço de sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 7, 'Então juntamente se aconselharam, e compraram com elas o campo do oleiro, para ser cemitério dos estrangeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 8, 'Por isso aquele campo tem sido chamado campo de sangue até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 9, 'Assim se cumpriu o que foi dito pelo profeta Jeremias, que disse: Tomaram as trinta [moedas] de prata, preço avaliado pelos filhos de Israel, o qual eles avaliaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 10, 'e as deram pelo campo do oleiro, conforme o que o Senhor me mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 11, 'Jesus esteve diante do governador, e o governador lhe perguntou: És tu o Rei dos Judeus? E Jesus lhe respondeu: Tu [o] dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 12, 'E, sendo ele foi acusado pelos chefes dos sacerdotes e pelos anciãos, nada respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 13, 'Pilatos, então, lhe disse: Não ouves quantas coisas estão testemunhando contra ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 14, 'Mas [Jesus] não lhe respondeu uma só palavra, de maneira que o governador ficou muito maravilhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 15, 'Na festa o governador costuma soltar um preso ao povo, qualquer um que quisessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 16, 'E tinham então um preso bem conhecido, chamado Barrabás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 17, 'Quando, pois, se ajuntaram, Pilatos lhes perguntou: Qual quereis que vos solte? Barrabás, ou Jesus, que é chamado Cristo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 18, 'Pois ele sabia que foi por inveja que o entregaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 19, 'E, enquanto ele estava sentado no assento de juiz, sua mulher lhe enviou a seguinte mensagem: Nada [faças] com aquele justo, pois hoje sofri muito em sonhos por causa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 20, 'Mas os chefes dos sacerdotes e os anciãos persuadiram as multidões a pedirem Barrabás, e a exigirem a morte de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 21, 'O governador lhes perguntou: Qual destes dois quereis que vos solte? E responderam: Barrabás!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 22, 'Pilatos lhes disse: Que, pois, farei de Jesus, que é chamado Cristo? Todos lhe disseram: Seja crucificado!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 23, 'E o governador perguntou: Ora, que mal ele fez? Porém gritavam mais: Seja crucificado!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 24, 'Quando, pois, Pilatos viu que nada adiantava, em vez disso se fazia mais tumulto, ele pegou água, lavou as mãos diante da multidão, e disse: Estou inocente do sangue deste justo. A responsabilidade é vossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 25, 'E todo o povo respondeu: O sangue dele [venha] sobre nós, e sobre os nossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 26, 'Então soltou-lhes Barrabás, enquanto que mandou açoitar Jesus, e o entregou para ser crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 27, 'Em seguida, os soldados do governador levaram Jesus consigo ao pretório, ajuntaram-se a ele toda a unidade miltar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 28, 'Eles o despiram e o cobriram com um manto vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 29, 'E, depois de tecerem uma coroa de espinhos, puseram-na sobre a sua cabeça, e uma cana em sua mão direita. Em seguida, puseram-se de joelhos diante dele, zombando-o, e diziam: Felicitações, Rei dos Judeus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 30, 'E cuspiram nele, tomaram a cana, e deram-lhe golpes na cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 31, 'Depois de terem o zombado, despiram-lhe a capa, vestiram-no com suas roupas, e o levaram para crucificar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 32, 'Ao saírem, encontraram um homem de Cirene, por nome Simão; e obrigaram-no a levar sua cruz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 33, 'E quando chegaram ao lugar chamado Gólgota, que significa “o lugar da caveira”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 34, 'deram-lhe de beber vinagre misturado com fel. E, depois de provar, não quis beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 35, 'E havendo-o crucificado, repartiram suas roupas, lançando sortes; para que se cumprisse o que foi dito pelo profeta: Repartiram entre si minhas roupas, e sobre minha túnica lançaram sortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 36, 'Então se sentaram, e ali o vigiavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 37, 'E puseram, por cima de sua cabeça, sua acusação escrita: ESTE É JESUS, O REI DOS JUDEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 38, 'Então foram crucificados com ele dois criminosos, um à direita, e outro à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 39, 'Os que passavam blasfemavam dele, balançando suas cabeças,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 40, 'e dizendo: Tu, que derrubas o Templo, e em três dias o reconstróis, salva a ti mesmo! Se és Filho de Deus, desce da cruz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 41, 'E da mesma maneira também os chefes dos sacerdotes, com os escribas e os anciãos, escarnecendo [dele] ,diziam:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 42, 'Salvou outros, a si mesmo não pode salvar. Se é Rei de Israel, desça agora da cruz, e creremos nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 43, 'Confiou em Deus, livre-o agora, se lhe quer bem; pois disse: “Sou Filho de Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 44, 'E os ladrões que estavam crucificados com ele também lhe insultavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 45, 'Desde a hora sexta houve trevas sobre toda a terra até a hora nona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 46, 'E perto da hora nona, Jesus gritou em alta voz: Eli, Eli, lamá sabactâni?, Isto é: Deus meu, Deus meu, porque me desamparaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 47, 'E alguns dos que ali estavam, quando ouviram, disseram: Ele está chamando Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 48, 'Logo um deles correu e tomou uma esponja. Então a encheu de vinagre, colocou-a em uma cana, e lhe dava de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 49, 'Porém os outros disseram: Deixa, vejamos se Elias vem livrá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 50, 'Jesus gritou outra vez em alta voz, e entregou o espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 51, 'E eis que o véu do Templo se rasgou em dois, de cima até embaixo, a terra tremeu, e as pedras se fenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 52, 'Os sepulcros se abriram, e muitos corpos de santos que tinham morrido foram ressuscitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 53, 'E, depois de ressuscitarem, saíram dos sepulcros, vieram à santa cidade, e apareceram a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 54, 'E o centurião, e os que com ele vigiavam Jesus, ao verem o terremoto e as coisas que haviam sucedido, tiveram muito medo, e disseram: Verdadeiramente ele era Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 55, 'Muitas mulheres, que desde a Galileia haviam seguido Jesus, e o serviam, estavam ali, olhando de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 56, 'Entre elas estavam Maria Madalena, e Maria mãe de Tiago e de José, e a mãe dos filhos de Zebedeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 57, 'E chegado o entardecer, veio um homem rico de Arimateia, por nome José, que também era discípulo de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 58, 'Ele chegou a Pilatos, e pediu o corpo de Jesus. Então Pilatos mandou que o corpo [lhe] fosse entregue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 59, 'José tomou o corpo, e o envolveu em um lençol limpo, de linho fino,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 60, 'e o pôs em seu sepulcro novo, que tinha escavado numa rocha; em seguida rolou uma grande pedra à porta do sepulcro, e foi embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 61, 'E ali estavam Maria Madalena e a outra Maria, sentadas de frente ao sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 62, 'No dia seguinte, que é o depois da preparação, os chefes dos sacerdotes, e os fariseus se reuniram com Pilatos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 63, 'e disseram: Senhor, nos lembramos que aquele enganador, enquanto ainda vivia, disse: “Depois de três dias serei ressuscitado”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 64, 'Portanto, manda que o sepulcro esteja em segurança até o terceiro dia, para que não aconteça dos seus discípulos virem de noite, e o furtem, e digam ao povo que ele ressuscitou dos mortos; e [assim] o último engano será pior que o primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 65, 'Pilatos lhes disse: Vós tendes uma guarda. Ide fazer segurança como o entendeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 27, 66, 'E eles se foram, e fizeram segurança no sepulcro com a guarda, selando a pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 1, 'No fim do sábado, quando já começava a clarear para o primeiro dia da semana, Maria Madalena, e a outra Maria vieram ver o sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 2, 'E eis que houve um grande terremoto; porque um anjo do Senhor desceu do céu, chegou, e moveu a pedra da entrada, e ficou sentado sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 3, 'A aparência dele era como um relâmpago, e sua roupa branca como neve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 4, 'E de medo dele os guardas tremeram muito, e ficaram como mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 5, 'Mas o anjo disse às mulheres: Não vos atemorizeis, pois eu sei que buscais Jesus, o que foi crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 6, 'Ele não está aqui, pois já ressuscitou, como ele disse. Vinde ver o lugar onde o Senhor jazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 7, 'Ide depressa dizer aos seus discípulos que ele ressuscitou dos mortos; e eis que vai adiante de vós para a Galileia; ali o vereis. Eis que eu tenho vos dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 8, 'Então elas saíram apressadamente do sepulcro, com temor e grande alegria, e correram para anunciar aos seus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 9, 'E, enquanto elas iam anunciar aos seus discípulos, eis que Jesus veio ao encontro delas, e disse: Saudações. Elas se aproximaram, pegaram os pés dele, e o adoraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 10, 'Jesus, então, lhes disse: Não temais. Ide anunciar aos meus irmãos para eles irem à Galileia, e ali me verão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 11, 'Enquanto elas iam, eis que alguns da guarda vieram à cidade, e anunciaram aos chefes dos sacerdotes tudo o que havia acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 12, 'Então eles se reuniram com os anciãos, depois de decidirem em conjunto, deram muito dinheiro aos soldados,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 13, 'dizendo: Falai: “Os discípulos dele vieram de noite, e o furtaram enquanto estávamos dormindo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 14, 'E, se isto for ouvido pelo governador, nós o persuadiremos, e vos manteremos seguros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 15, 'Eles tomaram o dinheiro e fizeram como foram instruídos. E este dito foi divulgado entre os judeus até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 16, 'Os onze discípulos se foram para a Galileia, ao monte onde Jesus havia lhes ordenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 17, 'E quando o viram, o adoraram; porém alguns duvidaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 18, 'Jesus se aproximou deles, e lhes falou: Todo o poder me é dado no céu e na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 19, 'Portanto ide, fazei discípulos a todas as nações, batizando-os em nome do Pai, do Filho, e do Espírito Santo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 28, 20, 'ensinando-lhes a guardar todas as coisas que eu vos tenho mandado. E eis que eu estou convosco todos os dias, até o fim dos tempos. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 1, 'Princípio do Evangelho de Jesus Cristo, Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 2, 'Como está escrito nos profetas: Eis que eu envio o meu mensageiro diante de tua face, que preparará o teu caminho diante de ti .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 3, 'Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai suas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 4, 'João veio a batizar no deserto, e a pregar o batismo de arrependimento para perdão dos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 5, 'E toda a província da Judeia e os de Jerusalém saíam até ele; e eram todos batizados por ele no rio Jordão, confessando os seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 6, 'João se vestia de pelos de camelo, e um cinto de couro em sua cintura; e comia gafanhotos e mel do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 7, 'Ele pregava assim: Após mim vem aquele que é mais forte do que eu. A ele não sou digno de me abaixar para desatar a tira das suas sandálias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 8, 'De fato eu tenho vos batizado com água, porém ele vos batizará com Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 9, 'E aconteceu que, naqueles dias, Jesus de Nazaré da Galileia veio, e foi batizado por João no Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 10, 'E assim que saiu da água, viu os céus se abrirem, e o Espírito, que como pomba descia sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 11, 'E veio uma voz dos céus: Tu és meu Filho amado, em quem me agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 12, 'E logo o Espírito o impeliu ao deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 13, 'Ele esteve ali no deserto quarenta dias, tentado por Satanás. Ele estava com os animais selvagens, e os anjos o serviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 14, 'Depois que João foi preso, Jesus veio para a Galileia, pregando o Evangelho do Reino de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 15, 'e dizendo: O tempo se cumpriu, e o Reino de Deus está perto; arrependei-vos, e crede no Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 16, 'E enquanto andava junto ao mar da Galileia, ele viu Simão e seu irmão André, que lançavam uma rede ao mar, porque eram pescadores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 17, 'Jesus lhes disse: Vinde após mim, e farei serdes pescadores de gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 18, 'Então logo deixaram suas redes, e o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 19, 'E passando dali um pouco mais adiante, viu Tiago [filho] de Zebedeu, e seu irmão João, que estavam no barco, consertando as redes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 20, 'E logo os chamou; então eles deixaram o seu pai Zebedeu no barco com os empregados, foram após ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 21, 'Eles entraram em Cafarnaum; e assim que chegou o sábado, [Jesus] entrou na sinagoga e começou a ensinar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 22, 'E ficavam admirados com o seu ensinamento, pois, diferentemente dos escribas, ele os ensinava como quem temautoridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 23, 'E havia na sinagoga deles um homem com um espírito imundo, que gritou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 24, 'dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Bem sei quem és: o Santo de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 25, 'Jesus o repreendeu, dizendo: Cala-te, e sai dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 26, 'E o espírito imundo, provocando convulsão nele, e gritando em alta voz, saiu dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 27, 'Assim todos ficaram admirados, e perguntavam entre si: Que é isto? Que novo ensinamento é este que, com autoridade, ordena até aos espíritos imundos, e eles lhe obedecem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 28, 'E logo sua fama se espalhou por toda a região da Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 29, 'Logo depois de saírem da sinagoga, vieram à casa de Simão e de André, com Tiago e João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 30, 'A sogra de Simão estava deitada com febre, e logo falaram dela [a Jesus] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 31, 'Então ele aproximou-se dela, tomou-a pela mão, e a levantou; logo a febre a deixou, e ela começou a servi-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 32, 'Ao entardecer, quando o sol já se punha, trouxeram-lhe todos os doentes e endemoninhados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 33, 'e toda a cidade se juntou à porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 34, 'Ele curou muitos que se achavam mal de diversas enfermidades, e expulsou muitos demônios. Ele não deixava os demônios falarem, porque o conheciam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 35, 'De madrugada, ainda escuro, ele se levantou para sair, foi a um lugar deserto, e ali esteve a orar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 36, 'Simão e os que estavam com ele o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 37, 'Quando o acharam, disseram-lhe: Todos estão te procurando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 38, '[Jesus] lhes respondeu: Vamos para as aldeias vizinhas, para que eu também pregue ali, pois vim para isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 39, 'Ele pregava em suas sinagogas por toda a Galileia, e expulsava os demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 40, 'Um leproso aproximou-se dele, rogando-lhe, pondo-se de joelhos diante dele, e dizendo-lhe: Se quiseres, tu podes limpar-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 41, 'E Jesus , movido de compaixão, estendeu a mão, tocou-o, e disse-lhe: Quero; sê limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 42, 'Quando disse isso, logo a lepra saiu dele, e ficou limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 43, '[Jesus] advertiu-o, e logo o despediu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 44, 'dizendo-lhe: Cuidado, não digas nada a ninguém. Mas vai, mostra-te ao Sacerdote, e oferece por teres ficado limpo o que Moisés mandou, para lhes servir de testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 1, 45, 'Porém, quando ele saiu, começou a anunciar muitas coisas, e a divulgar a notícia, de maneira que [Jesus] já não podia entrar publicamente na cidade; em vez disso, ficava do lado de fora em lugares desertos, e [pessoas] de todas as partes vinham até ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 1, 'Dias depois, [Jesus] entrou outra vez em Cafarnaum, e ouviu-se que estava em casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 2, 'Logo juntaram-se tantos, que nem mesmo perto da porta cabiam; e ele lhes falava a palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 3, 'E vieram a ele uns que traziam um paralítico carregado por quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 4, 'Como não podiam se aproximar dele por causa da multidão, descobriram o telhado onde ele estava, fizeram um buraco, e baixaram [por ele] o leito em que jazia o paralítico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 5, 'Quando Jesus viu a fé deles, disse ao paralítico: Filho, os teus pecados te são perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 6, 'E estavam ali sentados alguns escribas, que pensavam em seus corações:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 7, 'Por que este [homem] fala essas blasfêmias? Quem pode perdoar pecados, a não ser somente Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 8, 'Imediatamente Jesus percebeu em seu espírito que assim pensavam em si mesmos. Então perguntou-lhes: Por que pensais assim em vossos corações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 9, 'O que é mais fácil? Dizer ao paralítico: “Os teus pecados estão perdoados”, ou dizer, “Levanta-te, toma o teu leito, e anda”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 10, 'Mas para que saibais que o Filho do homem tem poder na terra para perdoar pecados,(disse ao paralítico):'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 11, 'A ti eu digo: levanta-te, toma o teu leito, e vai para a tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 12, 'E logo ele se levantou, tomou o leito, e saiu na presença de todos, de tal maneira, que todos ficaram admirados, e glorificaram a Deus, dizendo: Nunca vimos algo assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 13, '[Jesus] voltou a sair para o mar; toda a multidão veio até ele, e ele os ensinava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 14, 'E enquanto passava, ele viu Levi, [filho] de Alfeu, sentado no posto de coleta de impostos, e disse-lhe: Segue-me.Então [Levi] se levantou e o seguiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 15, 'E aconteceu que enquanto estava sentado à mesa na casa dele, muitos publicanos e pecadores também estavam assentados à mesa com Jesus e os seus discípulos; porque eram muitos, e o haviam seguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 16, 'Quando os escribas e os fariseus o viram comer com os publicanos e pecadores, disseram a seus discípulos: Por que é que ele come e bebe com os publicanos e os pecadores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 17, 'Jesus ouviu e lhes respondeu: Os que têm saúde não precisam de médico, mas sim os que estão doentes. Eu não vim para chamar os justos, mas sim, os pecadores, ao arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 18, 'Os discípulos de João e os dos fariseus estavam jejuando; então vieram lhe perguntar: Por que os discípulos de João e os dos fariseus jejuam, e os teus discípulos não jejuam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 19, 'Jesus lhes respondeu: Podem os convidados do casamento jejuar enquanto o noivo estiver com eles? Enquanto tiverem o noivo consigo, eles não podem jejuar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 20, 'Mas dias virão, quando o noivo lhes for tirado; e então naqueles dias jejuarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 21, 'Ninguém costura remendo de pano novo em roupa velha; senão o remendo novo rompe o velho, e se faz pior rasgo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 22, 'E ninguém põe vinho novo em odres velhos; senão o vinho novo rompe os odres, derrama-se o vinho, e os odres se danificam; mas o vinho novo deve ser posto em odres novos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 23, 'E aconteceu que, enquanto [Jesus] passava pelas plantações no sábado, os seus discípulos, andando, começaram a arrancar espigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 24, 'Os fariseus lhe disseram: Olha! Por que estão fazendo o que não é lícito no sábado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 25, 'E ele lhes disse: Nunca lestes o que fez Davi, quando teve necessidade e fome, ele e os que com ele estavam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 26, 'Como ele entrou na Casa de Deus, quando Abiatar era sumo sacerdote, e comeu os pães da proposição (dos quais não é lícito comer, a não ser aos sacerdotes), e também deu aos que com ele estavam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 27, 'Disse-lhes mais: O sábado foi feito por causa do ser humano, não o ser humano por causa do sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 2, 28, 'Por isso o Filho do homem é Senhor até do sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 1, '[Jesus] entrou outra vez na sinagoga; e estava ali um homem que tinha uma mão definhada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 2, 'E prestavam atenção nele, se o curaria no sábado, para o acusarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 3, 'E [Jesus] disse ao homem que tinha a mão definhada: Levanta-te, e vem para o meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 4, 'E disse-lhes:É lícito no sábado fazer o bem, ou o mal? Salvar uma pessoa, ou matá-la? E mantiveram-se calados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 5, 'E olhando ao redor para eles com indignação, sentindo pena da dureza dos seus corações, disse ao homem: Estende a tua mão. E ele estendeu; e sua mão foi restaurada , sã como a outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 6, 'Assim que os fariseus saíram, tiveram reunião com os herodianos contra ele, para combinarem sobre como o matariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 7, 'E Jesus retirou-se com os seus discípulos para o mar; e seguiu-o uma grande multidão da Galileia, da Judeia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 8, 'de Jerusalém, da Idumeia, dalém do Jordão, e os das proximidades de Tiro e de Sidom; uma grande multidão, tendo ouvido quão grandes coisas fazia, vieram a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 9, 'E disse aos seus discípulos que um barquinho ficasse continuamente perto dele, por causa das multidões; para que não o apertassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 10, 'Pois havia curado muitos, de maneira que todos quantos tinham algum mal lançavam-se sobre ele a fim de tocá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 11, 'E os espíritos imundos, quando o viam, prostravam-se diante dele, e exclamavam: Tu és o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 12, 'Mas [Jesus] os repreendia muito, para que não manifestassem quem ele era.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 13, 'Ele subiu ao monte, e chamou para si os que quis; então vieram a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 14, 'E constituiu doze para que estivessem com ele, para enviá-los a pregar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 15, 'para que tivessem poder de curar as enfermidades e expulsar os demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 16, 'Eram eles: Simão, a quem pôs por nome Pedro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 17, 'Tiago [filho] de Zebedeu, e João, irmão de Tiago; e pôs-lhes por nome Boanerges, que significa “filhos do trovão”;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 18, 'e André, Filipe, Bartolomeu, Mateus, Tomé; Tiago [filho] de Alfeu; Tadeu; Simão o zelote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 19, 'e Judas Iscariotes, o que o traiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 20, 'Quando foram para uma casa, outra vez se ajuntou uma multidão, de maneira que nem sequer podiam comer pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 21, 'Os seus [familiares] , ao ouvirem isso, saíram para detê-lo, porque diziam: “Ele stá fora de si”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 22, 'E os escribas que haviam descido de Jerusalém diziam: Ele tem Belzebu, e é pelo chefe dos demônios que expulsa demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 23, 'Então [Jesus] os chamou, e lhes disse por parábolas: Como pode Satanás expulsar Satanás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 24, 'Se algum reino estiver dividido contra si mesmo, tal reino não pode durar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 25, 'e se alguma casa estiver dividida contra si mesma, tal casa não pode durar firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 26, 'E se Satanás se levantar contra si mesmo, e for dividido, não pode durar, mas tem fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 27, 'Ninguém pode roubar os bens do valente, quando se entra na casa dele, se antes não amarrar ao valente; depois disso roubará a sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 28, 'Em verdade vos digo que todos os pecados serão perdoados aos filhos dos homens, e todas as blasfêmias com que blasfemarem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 29, 'mas quem blasfemar contra o Espírito Santo ficará sem perdão para sempre; em vez disso, é culpado do juízo eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 30, 'Pois diziam: “Ele tem espírito imundo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 31, 'Então chegaram os seus irmãos e a sua mãe ; e estando de fora, mandaram chamá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 32, 'A multidão estava sentada ao redor dele. Então disseram-lhe: Eis que a tua mãe e os teus irmãos estão lá fora a te procurar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 33, 'Ele lhes respondeu: Quem é a minha mãe ou os meus irmãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 34, 'E, olhando em redor aos que estavam sentados perto dele, disse: Eis aqui minha mãe e meus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 3, 35, 'Pois quem fizer a vontade de Deus, esse é meu irmão, minha irmã, e mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 1, '[Jesus] começou outra vez a ensinar junto ao mar, e uma grande multidão se ajuntou a ele, de maneira que ele entrou num barco e ficou sentado no mar; e toda a multidão estava em terra junto ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 2, 'E ensinava-lhes muitas coisas por parábolas; e dizia-lhes em seu ensinamento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 3, 'Ouvi: eis que o semeador saiu a semear;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 4, 'E aconteceu que, enquanto semeava, uma [parte das sementes] caiu junto ao caminho, e os pássaros do céu vieram, e a comeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 5, 'E outra caiu em pedregulhos, onde não havia muita terra; e logo nasceu, porque não tinha terra profunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 6, 'Mas, quando saiu o sol, queimou-se; e porque não tinha raiz, secou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 7, 'E outra caiu entre espinhos; e os espinhos cresceram e a sufocaram, e não deu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 8, 'Mas outra caiu em boa terra, e deu fruto, que subiu, e cresceu; e um deu trinta, outro sessenta, e outro cem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 9, 'E disse-lhes : Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 10, 'E quando [Jesus] esteve só, os que estavam junto dele, com os doze, perguntaram-lhe acerca da parábola .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 11, 'E respondeu-lhes: A vós é concedido saber o mistério do Reino de Deus; mas aos que são de fora, todas estas coisas se fazem por meio de parábolas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 12, 'para que vendo, vejam, e não percebam; e ouvindo, ouçam, e não entendam; para não haver de se converterem, e lhes sejam perdoados os pecados .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 13, 'E disse-lhes: Não sabeis o significado desta parábola? Como, pois, entendereis todas as parábolas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 14, 'O semeador semeia a palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 15, 'E estes são os de junto ao caminho: nos quais a palavra é semeada; mas depois de a ouvirem, Satanás logo vem, e tira a palavra que foi semeada nos seus corações .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 16, 'E, semelhantemente, estes são os que se semeiam em pedregulhos: os que havendo ouvido a palavra, logo a recebem com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 17, 'Mas não têm raiz em si mesmos; em vez disso, são temporários. Depois, quando se levanta a tribulação ou a perseguição por causa da palavra, logo tropeçam na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 18, 'E estes são os que se semeiam entre espinhos: os que ouvem a palavra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 19, 'mas as preocupações deste mundo, a sedução das riquezas, e as cobiças por outras coisas, entram, sufocam a palavra, e ela fica sem gerar fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 20, 'E estes são os que foram semeados em boa terra: os que ouvem a palavra, recebem-na, e dão fruto, um trinta, e outro sessenta, e outro cem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 21, 'E ele lhes disse: Por acaso a lâmpada vem a ser posta debaixo de uma caixa ou sob da cama? Não deve ela ser posta na luminária?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 22, 'Pois não há nada encoberto que não haja de ser revelado; e nada se faz [para ficar] encoberto, mas sim, para ser vir à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 23, 'Se alguém tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 24, 'E disse-lhes: Prestai atenção ao que ouvis: com a medida que medirdes a vós mesmos se medirá, e será acrescentado a vós que ouvis .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 25, 'Pois ao que tem, lhe será dado; e ao que não tem, até o que tem lhe será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 26, 'E dizia: Assim é o Reino de Deus, como se um homem lançasse semente na terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 27, 'e dormisse, e se levantasse, de noite e de dia, e a semente brotasse, e crescesse, sem que ele saiba como.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 28, 'Pois a terra de si mesma frutifica, primeiro a erva, depois a espiga, depois o grão cheio na espiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 29, 'E quando o fruto se mostra pronto, logo mete a foice, pois a colheita chegou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 30, 'E dizia: A que assemelharemos o Reino de Deus? Ou com que parábola o compararemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 31, 'Com um grão da mostarda que, quando semeado na terra, é a menor de todas as sementes na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 32, 'Mas, depois de semeado, cresce, e se torna a maior de todas as hortaliças, e cria grandes ramos, de maneira que os pássaros do céu podem fazer ninhos sob a sua sombra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 33, 'E com muitas parábolas como essas [Jesus ] lhes falava a palavra, conforme o que podiam ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 34, 'E não lhes falava sem parábola; mas aos seus discípulos explicava tudo em particular.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 35, 'Naquele dia, chegando o entardecer, disse-lhes: Passemos para o outro lado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 36, 'Então despediram a multidão, e o levaram consigo assim como estava no barco; mas havia também outros barquinhos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 37, 'E levantou-se uma grande tempestade de vento; as ondas atingiam por cima do barco, de maneira que já se enchia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 38, '[Jesus] estava na popa dormindo sobre uma almofada. Então despertaram-no, e disseram-lhe: Mestre, não te importas que pereçamos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 39, 'Então ele se levantou, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te! E o vento se aquietou, e fez-se grande bonança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 40, 'E perguntou-lhes: Por que sois tão covardes? Como não tendes fé?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 4, 41, 'E ficaram muito atemorizados, e diziam uns aos outros: Quem é este, que até o vento e o mar lhe obedecem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 1, 'E chegaram ao outro lado do mar, à terra dos Gadarenos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 2, 'Assim que [Jesus] saiu do barco, veio das sepulturas ao seu encontro um homem com um espírito imundo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 3, 'que morava nas sepulturas, e nem mesmo com correntes conseguiam prendê-lo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 4, 'pois muitas vezes fora preso com grilhões e correntes; mas as correntes eram por ele feitas em pedaços, os grilhões eram esmigalhados, e ninguém o conseguia controlar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 5, 'E sempre dia e noite andava gritando pelos montes e pelas sepulturas, e ferindo-se com pedras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 6, 'Quando ele viu Jesus de longe, correu e prostrou-se diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 7, 'E gritou em alta voz: Que tenho eu contigo Jesus, Filho do Deus Altíssimo? Imploro-te por Deus que não me atormentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 8, '(Pois [Jesus] havia lhe dito: “Sai deste homem, espírito imundo”.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 9, 'Então perguntou-lhe: Qual é o teu nome? E respondeu: Legião é o meu nome, porque somos muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 10, 'E rogava-lhe muito que não os expulsasse daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 11, 'Havia ali perto dos montes uma grande manada de porcos pastando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 12, 'E todos [aqueles ] demônios rogaram-lhe, dizendo: Manda-nos para aqueles porcos, para que entremos neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 13, 'Imediatamente Jesus lhes permitiu. Então aqueles espíritos imundos saíram para entrar nos porcos; e a manada lançou-se abaixo no mar; (eram quase dois mil) e afogaram-se no mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 14, 'Os que apascentavam os porcos fugiram, e avisaram na cidade e nos campos; e [as pessoas] foram ver o que havia acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 15, 'Então aproximaram-se de Jesus, e viram o endemoninhado sentado, vestido, e em sã consciência o que tivera a legião; e ficaram apavorados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 16, 'E os que haviam visto contaram-lhes o que acontecera ao endemoninhado, e sobre os porcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 17, 'Então começaram a rogar-lhe que saísse do território deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 18, 'Quando [Jesus] entrava no barco, o que fora endemoninhado rogou-lhe que estivesse com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 19, 'Jesus se recusou, porém lhe disse: Vai para a tua casa, aos teus, e anuncia-lhes quão grandes coisas o Senhor fez contigo, e [como] teve misericórdia de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 20, 'Então ele foi embora, e começou a anunciar em Decápolis quão grandes coisas Jesus havia feito com ele; e todos se admiravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 21, 'Depois de Jesus passar outra vez num barco para o outro lado, uma grande multidão se ajuntou a ele; e ele ficou junto ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 22, 'E eis que veio um dos líderes de sinagoga, por nome Jairo; e quando o viu, prostrou-se aos seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 23, 'E implorava-lhe muito, dizendo: Minha filhinha está a ponto de morrer. [Rogo-te] que venhas pôr as mãos sobre ela, para que seja curada, e viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 24, '[Jesus] foi com ele. Uma grande multidão o seguia, e o apertavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 25, 'E havia uma certa mulher, que tinha um fluxo de sangue havia doze anos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 26, 'que tinha sofrido muito por meio de muitos médicos, e gastado tudo quanto possuía, e nada havia lhe dado bom resultado; ao invés disso, piorava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 27, 'Quando ela ouviu falar de Jesus, veio entre a multidão por detrás, e tocou a roupa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 28, 'Pois dizia: Se tão somente tocar as suas roupas, serei curada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 29, 'E imediatamente a fonte do seu sangue parou se secou; e sentiu no corpo que já havia sido curada daquele flagelo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 30, 'Jesus logo notou em si o poder que dele havia saído. Então virou-se na multidão, e perguntou: Quem tocou as minhas roupas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 31, 'E seus discípulos lhe disseram: Eis que a multidão te aperta, e perguntas: Quem me tocou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 32, 'E ele olhava em redor, para ver quem havia lhe feito isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 33, 'Então a mulher temendo, e tremendo, sabendo o que havia sido feito em si, veio, prostrou-se diante dele, e disse-lhe toda a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 34, 'E ele lhe disse: Filha, a tua fé te salvou. Vai em paz, e estejas curada deste teu flagelo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 35, 'Estando ele ainda falando, alguns vieram [da casa] do líder de sinagoga, e disseram: A tua filha já morreu; por que ainda estás incomodando o Mestre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 36, 'Mas Jesus, assim que ouviu essa palavra que havia sido falada, disse ao líder de sinagoga: Não temas; crê somente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 37, 'E não permitiu que ninguém o seguisse, a não ser Pedro, Tiago, e João irmão de Tiago.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 38, 'Ele chegou à casa do líder de sinagoga, e viu o alvoroço, os que choravam muito e pranteavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 39, 'E ao entrar, disse-lhes: Por que fazeis alvoroço e chorais? A menina não morreu, mas está dormindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 40, 'E riram dele. Porém ele, depois de pôr todos fora, tomou consigo o pai e a mãe da menina, e os que estavam com ele. Em seguida, entrou onde a menina estava deitada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 41, 'Ele pegou a mão da menina, e lhe disse: “Talita cumi”, (que significa: “Menina, eu te digo, levanta-te”).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 42, 'E logo a menina se levantou e andou, pois já tinha doze anos de idade. E ficaram grandemente espantados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 5, 43, 'E mandou-lhes muito que ninguém o soubesse; e mandou que dessem a ela de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 1, '[Jesus] partiu-se dali, veio à sua terra, e seus discípulos o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 2, 'E chegando o sábado, começou a ensinar na sinagoga; e muitos, quando o ouviram, espantavam-se, dizendo: De onde lhe [vem] estas coisas? E que sabedoria é esta que lhe foi dada? E tais maravilhas feitas por suas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 3, 'Não é este o carpinteiro, filho de Maria, e irmão de Tiago, de José, de Judas, e de Simão? E não estão aqui as suas irmãs conosco? E ofenderam-se nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 4, 'E Jesus lhes dizia: Todo profeta tem honra, menos em sua terra, entre os parentes, e em sua própria casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 5, 'Ele não pôde ali fazer milagre algum, a não ser somente para uns poucos enfermos, sobre os quais pôs as mãos e os curou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 6, 'E ficou admirado da incredulidade deles. Ele percorreu as aldeias do redor, ensinando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 7, 'E chamou a si os doze, e começou a enviar de dois em dois; e deu-lhes poder sobre os espíritos imundos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 8, 'E mandou-lhes que não tomassem nada para o caminho, a não ser somente um bordão; nem bolsa, nem pão, nem dinheiro no cinto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 9, 'mas que calçassem sandálias, e não se vestissem de duas túnicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 10, 'E dizia-lhes: Onde quer que entrardes em alguma casa, ficai ali até que dali saiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 11, 'E todos os que não vos receberem, nem vos ouvirem, quando sairdes dali, sacudi o pó que estiver debaixo de vossos pés, em testemunho contra eles Em verdade vos digo, que mais tolerável será a [os de] Sodoma ou Gomorra no dia do juízo, do que a [os d] aquela cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 12, 'Eles, então, se foram, e pregaram que [as pessoas] se arrependessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 13, 'Eles expulsaram muitos demônios, e a muitos enfermos ungiram com azeite, e os curaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 14, 'O rei Herodes ouviu falar disso (porque o nome de [Jesus] já era notório). E dizia: João Batista ressuscitou dos mortos, e por isso estas maravilhas operam nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 15, 'Outros diziam: É Elias; e outros diziam: É profeta, ou como algum dos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 16, 'Quando, porém, Herodes ouviu falar disso, falou: Ele é João, de quem cortei a cabeça. Ele ressuscitou dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 17, 'Pois o próprio Herodes havia mandado prender João, e acorrentá-lo na prisão, por causa de Herodias, mulher do seu irmão Filipe, porque havia se casado com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 18, 'Pois João dizia a Herodes: Não te é lícito possuir a mulher do teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 19, 'Assim Herodias o odiava, e queria matá-lo, mas não podia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 20, 'pois Herodes temia João, sabendo que era um homem justo e santo, e o estimava. E quando o ouvia, fazia muitas coisas, o ouvia de boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 21, 'Mas veio um dia oportuno, em que Herodes, no dia do seu aniversário, dava uma ceia aos grandes de sua corte, aos comandantes militares, e aos principais da Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 22, 'Então a filha dessa Herodias entrou dançando, e agradou a Herodes e aos que estavam sentados com ele. O rei disse à garota: Pede-me quanto quiseres, que eu darei a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 23, 'E jurou a ela: Tudo o que me pedirdes te darei, até a metade do meu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 24, 'Então ela saiu, e perguntou à sua mãe: Que pedirei? E ela respondeu: A cabeça de João Batista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 25, 'E entrando ela logo apressadamente ao rei, pediu, dizendo: Quero que imediatamente me dês num prato a cabeça de João Batista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 26, 'E o rei entristeceu-se muito; [mas] , por causa dos juramentos, e dos que estavam juntamente à mesa, não quis recusar a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 27, 'Então logo o rei enviou o executor com a ordem de trazer ali sua cabeça. Ele, foi, e o decapitou na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 28, 'Em seguida, trouxe a sua cabeça num prato, e o deu à garota; e a garota a deu à sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 29, 'Quando os discípulos dele ouviram isso, vieram, pegaram o seu cadáver, e o puseram num sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 30, 'Os apóstolos juntaram-se [de volta] a Jesus, e contaram-lhe tudo, tanto o que haviam feito, como o que haviam ensinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 31, 'E ele lhes disse: Vinde vós à parte a um lugar deserto, e descansai um pouco; pois havia muitos que iam e vinham, e não tinham tempo para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 32, 'E foram-se num barco a um lugar deserto à parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 33, 'Mas as multidões os viram ir, e muitos o reconheceram. Então correram para lá a pé de todas as cidades, chegaram antes deles, e vieram para perto dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 34, 'Quando Jesus saiu [do barco] , viu uma grande multidão, e teve compaixão deles porque eram como ovelhas que não têm pastor. Assim, começou a lhes ensinar muitas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 35, 'E quando já era tarde, os seus discípulos vieram a ele, e disseram: O lugar é deserto, e a hora já é tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 36, 'Despede-os, para eles irem aos campos e aldeias circunvizinhos, e comprarem pão para si; pois não têm o que comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 37, 'Mas ele respondeu: Dai-lhes vós mesmos de comer. E eles lhe responderam: Iremos, e compraremos duzentos denários de pão, para lhes darmos de comer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 38, 'E ele lhes disse: Quantos pães tendes? Ide ver. Quando souberam, disseram: Cinco, e dois peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 39, 'E mandou-lhes que fizessem sentar a todos em grupos sobre a grama verde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 40, 'E sentaram-se repartidos de cem em cem, e de cinquenta em cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 41, 'Ele tomou os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou, e partiu os pães, e os deu aos seus discípulos, para que os pusessem diante deles. E os dois peixes repartiu com todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 42, 'Todos comeram e se saciaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 43, 'E dos pedaços de pão e dos peixes levantaram doze cestos cheios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 44, 'Os que comeram os pães eram quase cinco mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 45, 'Logo depois, ordenou seus discípulos a subirem no barco, e ir adiante para o outro lado, em Betsaida, enquanto ele despedia a multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 46, 'E, depois de os despedir, foi ao monte para orar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 47, 'Ao anoitecer, o barco estava no meio do mar, e [Jesus] sozinho em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 48, 'E viu que se cansavam muito remando, porque o vento lhes era contrário. Então, perto da quarta vigília da noite, veio a eles andando sobre o mar, e queria passar por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 49, 'Mas quando eles o viram andando sobre o mar, pensaram que era uma fantasma, e gritaram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 50, 'pois todos o viam, e ficaram perturbados. Então logo falou com eles, dizendo: Tende coragem! Sou eu, não tenhais medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 51, 'E subiu a eles no barco, e o vento se aquietou. Eles ficaram muito espantados e maravilhados entre si,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 52, 'pois não haviam entendido o que tinha acontecido com os pães, porque o coração deles estava endurecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 53, 'Eles terminaram de atravessar o mar, chegaram à terra de Genesaré, e ali aportaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 54, 'Quando eles saíram do barco, logo [as pessoas] o reconheceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 55, 'Então gente de toda a região em redor veio correndo, e começaram a trazer em camas os doentes, aonde quer que ouviam que ele estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 6, 56, 'E aonde quer que ele entrava, em povoados, cidades, ou aldeias, colocavam os enfermos nas praças, e rogavam-lhe que ao menos tocassem a borda de sua roupa; e todos os que o tocavam ficavam sarados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 1, 'Os fariseus, e alguns dos escribas, que tinham vindo de Jerusalém, reuniram-se com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 2, 'E, quando viram que alguns dos discípulos dele comiam pão com mãos impuras, isto é, sem lavar, repreendiam-lhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 3, '(Pois os fariseus, e todos os judeus, mantendo a tradição dos antigos, se não lavarem bastante as mãos, não comem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 4, 'E, quando voltam da rua, se não se lavarem, não comem; e há muitas outras coisas que se encarregam de guardar, [como] lavar os copos, as vasilhas, os utensílios de metal, e os leitos).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 5, 'Depois os fariseus e os escribas lhe perguntaram: Por que os teus discípulos não andam conforme a tradição dos antigos, em vez de comerem pão com as mãos sem lavar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 6, 'E ele lhes respondeu: Bem profetizou Isaías acerca de vós, hipócritas! Como está escrito: Este povo me honra com os lábios, mas o seu coração está longe de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 7, 'Eles, porém, me honram em vão, ensinando como doutrinas mandamentos humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 8, 'Pois vós deixais o mandamento de Deus, e mantendes a tradição humana, [como] lavar as vasilhas e os copos; e fazeis muitas outras coisas semelhantes a estas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 9, 'E dizia-lhes: Vós dispensais o mandamento de Deus para guardardes a vossa tradição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 10, 'porque Moisés disse: Honra o teu pai e a tua mãe. E quem maldisser ao pai ou à mãe terá de morrer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 11, 'Mas vós dizeis: Se o homem disser ao pai ou à mãe: Tudo o que te puder aproveitar de mim é corbã (isto é, oferta),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 12, 'então não lhe deixais mais nada fazer por seu pai ou por sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 13, 'Assim invalidaias a palavra de Deus por vossa tradição, que ordenastes; e [fazeis] muitas coisas semelhantes a estas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 14, 'E chamando para si toda a multidão, disse-lhes: Ouvi-me todos, e entendei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 15, 'Nada há fora do ser humano que nele entre que o possa contaminar; mas o que dele sai, isso é o que contamina o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 16, 'Se alguém tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 17, 'Quando [Jesus] deixou a multidão e entrou em casa, seus discípulos lhe perguntaram sobre a parábola.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 18, 'E ele lhes disse: Também vós estais assim sem entendimento? Não entendeis que tudo o que de fora entra no ser humano não o pode contaminar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 19, 'Pois não entra no seu coração, mas, sim, no ventre, e sai para a privada. (Assim, ele declarou como limpas todas as comidas).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 20, 'E dizia: O que sai do ser humano, isso contamina o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 21, 'Pois é de dentro do coração humano que vêm os maus pensamentos, os adultérios, os pecados sexuais, os homicídios,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 22, 'os roubos, as ganâncias, as maldades, o engano, a depravação, o olho malicioso, a blasfêmia, a soberba, a insensatez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 23, 'Todos estes males procedem de dentro, e contaminam o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 24, '[Jesus] levantou-se dali e foi para a região de Tiro e de Sidom. Ele entrou numa casa, e não queria que ninguém soubesse disso, mas não pôde se esconder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 25, 'Pois uma mulher, cuja filhinha tinha um espírito imundo, assim que ouviu falar dele, veio, e prostrou-se a seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 26, 'Esta mulher era grega, de nacionalidade sirofenícia; e rogava-lhe que expulsasse o demônio de sua filha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 27, 'Mas Jesus lhe disse: Deixa primeiro que os filhos se fartem; porque não é bom tomar o pão dos filhos, e lançá-lo aos cachorrinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 28, 'Porém ela lhe respondeu: Sim Senhor; mas também os cachorrinhos comem debaixo da mesa, das migalhas que os filhos deixam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 29, 'Então ele lhe disse: Por esta palavra, vai, o demônio já saiu da tua filha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 30, 'Quando ela chegou à sua casa, encontrou que o demônio já havia saído, e a filha estava deitada sobre a cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 31, 'Então [Jesus] voltou a sair da região de Tiro e de Sidom, e veio para o mar da Galilea, por meio da região de Decápolis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 32, 'E trouxeram-lhe um surdo que dificilmente falava, e rogaram-lhe que pusesse a mão sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 33, 'E tomando-o em separado da multidão, pôs os seus dedos nos ouvidos dele, cuspiu, e tocou-lhe a língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 34, 'Depois, levantando os olhos ao céu, suspirou, e disse: Efatá, (isto é, abre-te).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 35, 'Imediatamente os ouvidos dele se abriram, e o que prendia sua língua se soltou, e passou a falar bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 41, 'Marcos', 'Mc', 7, 36, '[Jesus] lhes mandou que a ninguém dissessem; porém, quanto mais lhes mandava, mais divulgavam.')
